int usb_probe_device(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct can_device_config *host_config;
    struct can_device_config *device_config;
    struct can_device *can_dev;
    int ret, intf_count;

    host_config = kmalloc(sizeof(struct can_device_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    device_config = kmalloc(sizeof(struct can_device_config), GFP_KERNEL);
    if (!device_config) {
        ret = -ENOMEM;
        goto free_host_config;
    }

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          CAN_SET_CONFIGURATION, 0, 0, host_config,
                          sizeof(struct can_device_config), USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto free_device_config;

    ret = usb_get_device_config(intf, device_config);
    if (ret < 0)
        goto free_device_config;

    intf_count = device_config->num_interfaces;
    if (intf_count > MAX_USB_INTERFACES) {
        ret = -EINVAL;
        goto free_device_config;
    }

    can_dev = kmalloc(sizeof(struct can_device), GFP_KERNEL);
    if (!can_dev) {
        ret = -ENOMEM;
        goto free_device_config;
    }

    can_dev->host_config = host_config;
    can_dev->device_config = device_config;
    can_dev->interface_count = intf_count;

    ret = can_init_device(can_dev);
    if (ret < 0) {
        kfree(can_dev);
        goto free_device_config;
    }

    usb_set_intfdata(intf, can_dev);

    return 0;

free_device_config:
    kfree(device_config);
free_host_config:
    kfree(host_config);
    return ret;
}

int usb_probe_init(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_config;
    struct device_config *device_config;
    int ret = 0;

    host_config = kzalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    ret = usb_control_msg(intf->cur_altsetting->actconfig->interface, USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_REQ_SET_CONFIGURATION, 0, 0, host_config, sizeof(*host_config), 1000);
    if (ret < 0)
        goto free_host;

    device_config = kzalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config) {
        ret = -ENOMEM;
        goto free_host;
    }

    ret = usb_get_device_descriptor(intf->cur_altsetting->actconfig->interface, device_config);
    if (ret < 0)
        goto free_device;

    if (device_config->num_interfaces > MAX_INTERFACES) {
        ret = -EINVAL;
        goto free_device;
    }

    struct can_device *can_dev;
    can_dev = can_alloc_dev();
    if (!can_dev) {
        ret = -ENOMEM;
        goto free_device;
    }

    // Initialize can_dev and register with CAN subsystem (example placeholder logic)
    ret = can_dev->init(can_dev);
    if (ret < 0)
        goto free_can_dev;

    ret = register_can_device(can_dev);
    if (ret < 0)
        goto free_can_dev;

    return 0;

free_can_dev:
    can_free_dev(can_dev);
free_device:
    kfree(device_config);
free_host:
    kfree(host_config);
    return ret;
}

int usb_init_device(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_cfg;
    struct device_config *dev_cfg;
    int ret;

    host_cfg = kmalloc(sizeof(*host_cfg), GFP_KERNEL);
    if (!host_cfg)
        return -ENOMEM;

    dev_cfg = kmalloc(sizeof(*dev_cfg), GFP_KERNEL);
    if (!dev_cfg) {
        ret = -ENOMEM;
        goto free_host_cfg;
    }

    ret = usb_control_msg(
        interface_to_usbdev(intf),
        usb_sndctrlpipe(interface_to_usbdev(intf), 0),
        SET_HOST_CONFIG,
        USB_TYPE_CLASS | USB_RECIP_DEVICE,
        0,
        0,
        host_cfg,
        sizeof(*host_cfg),
        USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto free_dev_cfg;

    ret = get_device_config(interface_to_usbdev(intf), dev_cfg);
    if (ret < 0)
        goto free_dev_cfg;

    if (dev_cfg->num_interfaces > MAX_INTERFACES) {
        ret = -EINVAL;
        goto free_dev_cfg;
    }

    dev = kmalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev) {
        ret = -ENOMEM;
        goto free_dev_cfg;
    }

    init_device(dev, host_cfg, dev_cfg);

    for (int i = 0; i < dev_cfg->num_interfaces; i++) {
        struct can_device *can_dev = alloc_can_device();
        if (!can_dev) {
            ret = -ENOMEM;
            while (i > 0) {
                --i;
                free_can_device(dev->can_devs[i]);
            }
            goto free_dev;
        }

        dev->can_devs[i] = can_dev;
    }

    return 0;

free_dev:
    kfree(dev);
free_dev_cfg:
    kfree(dev_cfg);
free_host_cfg:
    kfree(host_cfg);
    return ret;
}

int usb_init_device(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_config;
    struct device_config *device_config;
    struct device *device;
    int num_interfaces;
    int error = 0;

    host_config = kzalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    device_config = kzalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config) {
        error = -ENOMEM;
        goto free_host_config;
    }

    error = usb_control_msg(interface_to_usbdev(intf), usb_sndctrlpipe(interface_to_usbdev(intf), 0),
                            USB_REQUEST_SET_CONFIG, USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                            0, 0, host_config, sizeof(*host_config), USB_CTRL_MSG_TIMEOUT);
    if (error < 0)
        goto free_device_config;

    num_interfaces = get_num_interfaces(device_config);
    if (num_interfaces <= 0 || num_interfaces > MAX_INTERFACES) {
        error = -EINVAL;
        goto free_device_config;
    }

    device = kzalloc(sizeof(*device), GFP_KERNEL);
    if (!device) {
        error = -ENOMEM;
        goto free_device_config;
    }

    init_device(device, device_config, num_interfaces);

    for (int i = 0; i < num_interfaces; i++) {
        error = create_can_device_instance(device, i);
        if (error < 0)
            goto free_can_devices;
    }

    return 0;

free_can_devices:
    for (int i = 0; i < num_interfaces; i++)
        free_can_device(device, i);
    kfree(device);
free_device_config:
    kfree(device_config);
free_host_config:
    kfree(host_config);
    return error;
}

int usb_probe_and_configure(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_cfg;
    struct device_config *dev_cfg;
    int ret;

    host_cfg = kmalloc(sizeof(*host_cfg), GFP_KERNEL);
    if (!host_cfg)
        return -ENOMEM;

    dev_cfg = kmalloc(sizeof(*dev_cfg), GFP_KERNEL);
    if (!dev_cfg) {
        kfree(host_cfg);
        return -ENOMEM;
    }

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber, 0x40, host_cfg);
    if (ret < 0) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return ret;
    }

    ret = usb_get_device_config(intf->cur_altsetting->desc.bInterfaceNumber, dev_cfg);
    if (ret < 0) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return ret;
    }

    if (dev_cfg->num_interfaces > MAX_INTERFACES) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return -EINVAL;
    }

    struct can_device *can_dev = can_dev_alloc();
    if (!can_dev) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return -ENOMEM;
    }

    can_dev_init(can_dev, host_cfg, dev_cfg);

    return 0;
}
